DO $ay$
DECLARE expected_delta bigint; packs jsonb := $pack$[{"codigo":"S22AR-274-1","legacy_id":274,"version_nucleo":2,"relacionadas":[],"coberturas":[{"legacy_id":274,"estado_cobertura":"PARCIAL","residual":"Falta confirmar con proveedor elegido si admite cobro recurrente/tokenizado Yape sin acción del cliente y falta su fila en tabla de proveedores; falta binding físico de acepta_yape_en_cuotas por aliado y del recordatorio parametrizable. No se inventa proveedor ni capacidad.","diferencias":"Nueva decisión dueño 2026-11-26: Yape en cuotas por proveedor distinto, confirmación manual mensual si no hay recurrencia acreditada; actualiza versión existente sin duplicar regla."}],"paquete":{"tipo":"CAMBIO","codigo":"S22AR-274-1","clave":"s22ar_legacy_274_0","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Elegibilidad Yape en cuotas","descripcion":"BLOQUEAR habilitación de Yape en cuotas sin elegibilidad server-side y campo aliado acepta_yape_en_cuotas. Si false, cuotas posteriores al pago inicial solo tarjeta; si true, Yape elegible también para cuotas mediante proveedor distinto del de tarjeta, elegido por canal desde tabla de proveedores activos, sin identificador fijo en código. Si hay varios activos, selección por canal según tabla; no inventar desempate. Mostrar únicamente logo Yape, sin nombre ni logo de proveedor. Pago inicial sujeto a elegibilidad propia. No habilitar proveedor no acreditado. Binding runtime pendiente; no modifica IG ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/274","solicitante":"Cristhian / Claude S22-AY"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ay_yape_eligibility"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ay_yape_ally_config_ignored"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ay_yape_initial_ineligible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_not_configured"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_same_as_card"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_selection_not_by_channel"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_brand_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_other_logo_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_card_only_despite_eligible"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":true,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":true,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":true,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":true,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":true,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":true,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":true,"ay_yape_card_only_despite_eligible":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":true,"ay_yape_ally_config_ignored":false,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_eligibility":false,"ay_yape_ally_config_ignored":true,"ay_yape_initial_ineligible":false,"ay_yape_provider_not_configured":false,"ay_yape_provider_same_as_card":false,"ay_yape_provider_selection_not_by_channel":false,"ay_yape_provider_brand_visible":false,"ay_yape_other_logo_visible":false,"ay_yape_card_only_despite_eligible":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"543d180b197045e7a2f43b1c97b22304eb56a969b38e342a1236fcf92da94580","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AR-286-1","legacy_id":286,"version_nucleo":2,"relacionadas":["S22AR-274-1"],"coberturas":[{"legacy_id":286,"estado_cobertura":"PARCIAL","residual":"Falta confirmar con proveedor elegido si admite cobro recurrente/tokenizado Yape sin acción del cliente y falta su fila en tabla de proveedores; falta binding físico de acepta_yape_en_cuotas por aliado y del recordatorio parametrizable. No se inventa proveedor ni capacidad.","diferencias":"Nueva decisión dueño 2026-11-26: Yape en cuotas por proveedor distinto, confirmación manual mensual si no hay recurrencia acreditada; actualiza versión existente sin duplicar regla."}],"paquete":{"tipo":"CAMBIO","codigo":"S22AR-286-1","clave":"s22ar_legacy_286_0","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Yape en cronograma regular","descripcion":"BLOQUEAR restricción fija de Yape al pago inicial cuando aliado acepta_yape_en_cuotas y proveedor configurado lo admite. Para pago Yape con acción cliente, ingresar celular y código de aprobación Yape y confirmar cada cuota; si proveedor no soporta cobro recurrente sin acción cliente, usar confirmación mensual con recordatorio previo parametrizable por tipo de cliente conforme política de notificaciones. Solo permitir cobro recurrente automático/tokenizado sin acción si capacidad del proveedor está acreditada y autorización explícita aplicable registrada. No asumir recurrencia, no solicitar tarjeta adicional cuando Yape manual elegible, no mostrar nombre/logo proveedor; solo logo Yape. Binding runtime pendiente; no modifica IG ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/286","solicitante":"Cristhian / Claude S22-AY"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ay_yape_collection"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ay_yape_regular_denied_despite_eligible"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ay_yape_recurring_without_evidence"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_missing_phone_or_code"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_without_confirmation"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_reminder_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_reminder_not_customer_config"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_autodebit_consent_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_brand_in_collection"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":true,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":true,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":true,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":true,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":true,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":true,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":true,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":false,"ay_yape_regular_denied_despite_eligible":true,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"7f9bdd0bb03ad1a99d05c27e3030fca94a428caa6804677a3d8afd5e0d3ea809","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb; v integer;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM v THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=v LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 10:40 Lima: Revisado conforme; S22AR-274-1 y S22AR-286-1 CAMBIO v2, ambas parciales; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AY_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AY_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=v AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AY_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int; h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AY_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AY_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,v,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 10:40 Lima'),h,'GPT / Claude S22-AY independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AY_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AY_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AY_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AY_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $ay$;
COMMIT;
